export const meta = {
  name: 'audit-foldertree-guard',
  description: 'Audit every web call site of folderTree-dependent CipherBoxClient methods for a missing ensureFolderRegistered guard',
  phases: [
    { title: 'Audit', detail: 'parallel agents trace each client-method family to its web call sites' },
    { title: 'Verify', detail: 'adversarially confirm flagged gaps are real and reachable' },
  ],
}

const REPO = '/Users/myankelev/Code/random/cipher-box'

const GROUND_TRUTH = `
REPO: ${REPO} (cwd). This is an audit for a SPECIFIC bug class.

THE BUG CLASS (just fixed in commit fc05bf87b on branch fix/owner-edit-folder-not-loaded):
Several CipherBoxClient methods in packages/sdk/src/client.ts gate on the in-memory folderTree:
  const folder = this.folderTree.get(<ipnsName>);
  if (!folder) throw new Error('Folder not loaded');   // hard-throw
…or they dereference folderTree.get(...) WITHOUT a guard (would crash on undefined).
The web app populates folderTree ONLY via ensureFolderRegistered(folderNode) (apps/web/src/lib/sdk-provider.ts:96).
Navigation/read populate ONLY the Zustand store (useFolderStore), NEVER folderTree. So after the SDK client is
re-created (e.g. page reload, logout/login, reconfigurePinning) with an EMPTY folderTree, any web call that routes
through a folderTree-dependent client method WITHOUT first calling ensureFolderRegistered(parentFolder) for the
relevant folder throws 'Folder not loaded' (or crashes) the first time it runs before any mutation re-registers it.

AUTHORITATIVE LIST — folderTree-dependent client methods (packages/sdk/src/client.ts):
  HARD-THROW ('Folder not loaded'):
    renameItem (line ~499), deleteItem (~626), uploadFile (~694), uploadFiles (~888),
    replaceFile (~1162) [ALREADY FIXED], restoreFileVersion (~1274) [ALREADY FIXED],
    deleteFileVersion (~1357) [ALREADY FIXED], shareFolder (~1723)
  DEREF folderTree.get (verify whether undefined throws/crashes):
    createFolder/createSubfolder (reads parent at ~399), moveItem (reads source ~551 + dest ~552),
    deleteToBin (~1568), restoreFromBin (~1604), collectSubtreeIpnsNames (private, ~211)
  SAFE (NOT folderTree-dependent — do NOT flag): getContext, downloadFromIpns, loadBin, hasFolder,
    registerFolder, getSequenceNumber. (downloadFromIpns/loadBin resolve IPNS directly; verify if unsure.)

EXISTING ensureFolderRegistered guards in apps/web (the ones already present):
  useFolderMutations.ts: lines 114,171,217,218,301,302,346,396,425
  useDropUpload.ts: 109 ; useFileVersions.ts: 66,181 ; useFileOperations.ts: 80

WEB CALL SITES discovered (both getSdkClient().X( and const client=getSdkClient(); client.X( styles):
  useFolderMutations.ts: createFolder@118, renameItem@175, moveItem@222, moveItem@307, deleteItem@~26/~32, deleteToBin@~29
  useDropUpload.ts: uploadFiles@147
  apps/web/src/services/encrypt-worker.service.ts: uploadFiles@102   <-- VERIFY: is this the SDK client? guarded?
  useBin.ts: restoreFromBin@73/@128, permanentDelete@90/@146, emptyBin@107
  useFileOperations.ts: replaceFile@118 [fixed], useFileVersions.ts: restoreFileVersion@109 + deleteFileVersion@223 [fixed]
  shareFolder: caller(s) NOT yet located — FIND every web caller of client.shareFolder.
NOTE: the call-site list may be INCOMPLETE — also search for client aliases passed into controllers/services, shared-folder
navigation write paths, and any other invocation style. Do not assume the list is exhaustive.

A "GAP" = a web call site that reaches a folderTree-dependent client method where the relevant folder is NOT guaranteed
to be in folderTree at call time: i.e. no preceding ensureFolderRegistered(folder) for THAT folder on ALL code paths,
AND the folder is not freshly created by that same op (a brand-new folder legitimately won't be in folderTree — e.g.
createFolder's NEW child, or moveItem's destination if it's the just-created folder). Report SAFE only when you can show
the folder is always registered (or the method is not folderTree-dependent). When unsure, mark uncertain — do not guess SAFE.
`

const AUDIT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['family', 'callSites'],
  properties: {
    family: { type: 'string' },
    callSites: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['clientMethod', 'webFile', 'webLine', 'folderParam', 'guardedBy', 'verdict', 'evidence', 'reachableScenario'],
        properties: {
          clientMethod: { type: 'string' },
          webFile: { type: 'string' },
          webLine: { type: 'string' },
          folderParam: { type: 'string', description: 'which folder/ipns the method needs in folderTree' },
          guardedBy: { type: 'string', description: 'file:line of the preceding ensureFolderRegistered for that folder, or "NONE"' },
          verdict: { type: 'string', enum: ['safe', 'gap', 'uncertain'] },
          evidence: { type: 'string', description: 'code-level proof: the client guard line + the web path' },
          reachableScenario: { type: 'string', description: 'if gap: the concrete sequence (e.g. reload then this op) that throws; if safe: why it cannot throw' },
        },
      },
    },
    extraCallSitesFound: { type: 'string', description: 'any call sites beyond the provided list, or "none"' },
  },
}

phase('Audit')

const FAMILIES = [
  {
    key: 'mutations',
    prompt: `${GROUND_TRUTH}

YOUR FAMILY: folder mutations in apps/web/src/hooks/useFolderMutations.ts — createFolder, renameItem, moveItem (single + any batch moveItems), deleteItem, deleteToBin. For EACH client call, trace upward in the same handler and confirm whether ensureFolderRegistered is called for the EXACT folder the client method will folderTree.get(). Pay attention to: moveItem needs BOTH source and dest registered; the lines ~26/~29/~32 client.deleteItem/deleteToBin calls (figure out what enclosing helper that is and whether its callers register); the createFolder NEW-subfolder case (the new child folder is legitimately not in folderTree — that's fine, but the PARENT must be). Read the actual client.ts method bodies to confirm what each derefs/throws.`,
  },
  {
    key: 'uploads',
    prompt: `${GROUND_TRUTH}

YOUR FAMILY: uploads — client.uploadFiles / uploadFile. Two call sites: apps/web/src/hooks/useDropUpload.ts:147 and apps/web/src/services/encrypt-worker.service.ts:102. For each, determine whether the 'client' is the SDK CipherBoxClient, and whether ensureFolderRegistered(parentFolder) runs before the upload on ALL paths. encrypt-worker.service.ts is the SUSPICIOUS one — read it fully: where does its 'client' come from, what parentFolder does it upload into, and is that folder guaranteed registered (or is it only ever reached via a hook that already registered)? Trace the callers of the worker service if needed.`,
  },
  {
    key: 'share',
    prompt: `${GROUND_TRUTH}

YOUR FAMILY: sharing — client.shareFolder (packages/sdk/src/client.ts ~1723, hard-throws 'Folder not loaded'). FIND every web caller of shareFolder (grep apps/web for shareFolder, and for any controller/service the share dialog uses). For each caller, confirm whether ensureFolderRegistered(folder) precedes it for the folder being shared. The share flow (ShareDialog / share.service / useShare*) is the likely location. This method had NO known guard in the initial sweep — scrutinize it. Also check related share-write paths (updateSharePermission, revokeShare, addShareKeys) for any folderTree dependency.`,
  },
  {
    key: 'bin',
    prompt: `${GROUND_TRUTH}

YOUR FAMILY: bin operations in apps/web/src/hooks/useBin.ts — restoreFromBin, permanentDelete, emptyBin, and deleteToBin (the client side at ~1568 restoreFromBin/deleteToBin). Read client.ts deleteToBin (~1568) and restoreFromBin (~1604): do they folderTree.get a TARGET folder and crash/throw if absent? restoreFromBin restores an item back into a target folder — that target folder must be in folderTree. Check whether useBin registers it. permanentDelete/emptyBin likely operate on bin records (not folderTree) — confirm. Determine if a post-reload "open bin, restore an item" sequence throws.`,
  },
  {
    key: 'sweep',
    prompt: `${GROUND_TRUTH}

YOUR FAMILY: COMPLETENESS SWEEP. Do not trust the provided call-site list. Independently enumerate EVERY way apps/web invokes a folderTree-dependent CipherBoxClient method: grep for getSdkClient(), every variable assigned from it, every method name in the authoritative list, any client instance passed into a service/controller/worker, and the shared-folder navigation WRITE paths (useSharedNavigation / SharedFileBrowser / shared-write wiring — recipients editing/uploading into a shared folder may or may not go through folderTree). Report any call site NOT already covered by the mutations/uploads/share/bin families, and whether it is guarded. Your job is to find anything the other four families would miss.`,
  },
]

const audits = await parallel(
  FAMILIES.map((f) => () => agent(f.prompt, { label: `audit:${f.key}`, phase: 'Audit', schema: AUDIT_SCHEMA }))
)

const valid = audits.filter(Boolean)
const allSites = valid.flatMap((a) => (a.callSites || []).map((c) => ({ ...c, family: a.family })))
const gaps = allSites.filter((c) => c.verdict === 'gap' || c.verdict === 'uncertain')
log(`Audit: ${allSites.length} call sites, ${gaps.length} flagged (gap/uncertain)`)

phase('Verify')

const VERIFY_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['clientMethod', 'webFile', 'webLine', 'isRealGap', 'reasoning', 'fix'],
  properties: {
    clientMethod: { type: 'string' },
    webFile: { type: 'string' },
    webLine: { type: 'string' },
    isRealGap: { type: 'boolean', description: 'true only if a post-client-recreation call deterministically throws/crashes here with no preceding registration' },
    reasoning: { type: 'string', description: 'verified against committed client.ts + web source; rule out false positive' },
    fix: { type: 'string', description: 'if real: the exact minimal fix (file:line + the ensureFolderRegistered call), mirroring fc05bf87b; else "n/a"' },
  },
}

let verified = []
if (gaps.length > 0) {
  verified = (
    await parallel(
      gaps.map((g) => () =>
        agent(
          `${GROUND_TRUTH}

A prior audit flagged this as a possible GAP (verdict=${g.verdict}):
  clientMethod: ${g.clientMethod}
  webFile/line: ${g.webFile}:${g.webLine}
  folderParam: ${g.folderParam}
  guardedBy: ${g.guardedBy}
  evidence: ${g.evidence}
  reachableScenario: ${g.reachableScenario}

Adversarially VERIFY against the actual committed source (Read packages/sdk/src/client.ts for the method body and the web file). Confirm whether a real, reachable bug exists: does the folder method dereference/throw on a missing folderTree entry AND can the relevant folder genuinely be absent at this call site after a client re-creation with no intervening ensureFolderRegistered? Default isRealGap:false unless you can point to the exact throw/deref line and a concrete reachable sequence. If real, give the precise minimal fix.`,
          { label: `verify:${g.clientMethod}@${g.webLine}`, phase: 'Verify', schema: VERIFY_SCHEMA }
        )
      )
    )
  ).filter(Boolean)
}

const confirmed = verified.filter((v) => v.isRealGap)
return {
  totalCallSites: allSites.length,
  safe: allSites.filter((c) => c.verdict === 'safe').map((c) => `${c.clientMethod} @ ${c.webFile}:${c.webLine}`),
  flagged: gaps.map((g) => `${g.clientMethod} @ ${g.webFile}:${g.webLine} (${g.verdict})`),
  confirmedGaps: confirmed,
  extraFindings: valid.map((a) => a.extraCallSitesFound).filter((x) => x && x !== 'none'),
}

